mapper.select:
SELECT id as ID, test_id as testId, name as name, description as description, priority as priority, status as status, created_at as createdAt, assignee as assignee, fix_due_date as fixDueDate, fixed_date as fixedDate, remarks as remarks, is_deleted as isDeleted, updated_at as updatedAt, pjt_id as pjtId, assigneeName, testName, priorityName, statusName FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT d.id, d.test_id, d.name, d.description, d.priority, d.status, d.created_at, d.assignee, d.fix_due_date, d.fixed_date, d.remarks, d.is_deleted, d.updated_at, d.pjt_id, COALESCE(u.name, d.assignee) as assigneeName, ut.TEST_CASE_NAME as testName, (CASE d.priority WHEN 'CR' THEN '긴급' WHEN 'HI' THEN '높음' WHEN 'MD' THEN '보통' WHEN 'LO' THEN '낮음' ELSE d.priority END) as priorityName, (CASE d.status WHEN 'NEW' THEN '신규' WHEN 'IPR' THEN '진행중' WHEN 'FIX' THEN '해결' WHEN 'REO' THEN '재오픈' WHEN 'COM' THEN '완료' ELSE d.status END) as statusName FROM defect d LEFT JOIN users u ON d.assignee = u.user_id LEFT JOIN unit_test_case ut ON d.test_id = ut.id WHERE d.is_deleted = 'N'
AND d.name LIKE CONCAT('%', #{name}, '%')
AND d.status = #{status}
AND d.assignee LIKE CONCAT('%', #{assignee}, '%')
AND d.priority = #{priority}
AND d.test_id LIKE CONCAT('%', #{testId}, '%')
AND DATE(d.created_at) >= #{dateFrom}
AND DATE(d.created_at) <= #{dateTo}
AND d.pjt_id = #{pjtId}
ORDER BY d.created_at DESC ) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}

SELECT COUNT(*)
FROM defect d
LEFT JOIN users u ON d.assignee = u.user_id
LEFT JOIN unit_test_case ut ON d.test_id = ut.id
WHERE d.is_deleted = 'N'

    AND d.name LIKE CONCAT('%', #{name}, '%')


    AND d.status = #{status}


    AND (d.assignee LIKE CONCAT('%', #{assignee}, '%') OR u.name LIKE CONCAT('%', #{assignee}, '%'))


    AND d.priority = #{priority}


    AND d.test_id LIKE CONCAT('%', #{testId}, '%')



    AND DATE(d.created_at) >= #{dateFrom}


    AND DATE(d.created_at) <= #{dateTo}


    AND d.pjt_id = #{pjtId}

SELECT status as status, COUNT(*) as count FROM defect WHERE is_deleted = 'N'
AND pjt_id = #{pjtId}
AND assignee = #{assignee}
GROUP BY status ORDER BY status

SELECT priority as priority, COUNT(*) as count FROM defect WHERE is_deleted = 'N'
AND pjt_id = #{pjtId}
AND assignee = #{assignee}
GROUP BY priority ORDER BY CASE priority WHEN 'CR' THEN 1 WHEN 'HI' THEN 2 WHEN 'MD' THEN 3 WHEN 'LO' THEN 4 ELSE 5 END

SELECT d.assignee as assignee, COALESCE(u.name, d.assignee) as assigneeName, COUNT(*) as count FROM defect d LEFT JOIN users u ON d.assignee = u.user_id WHERE d.is_deleted = 'N'
AND d.pjt_id = #{pjtId}
GROUP BY d.assignee, u.name ORDER BY count DESC

SELECT id as ID, test_id as testId, name as name, description as description, priority as priority, status as status, created_at as createdAt, assignee as assignee, fix_due_date as fixDueDate, fixed_date as fixedDate, remarks as remarks, is_deleted as isDeleted, updated_at as updatedAt, pjt_id as pjtId, assigneeName, testName, priorityName, statusName FROM ( SELECT d.id, d.test_id, d.name, d.description, d.priority, d.status, d.created_at, d.assignee, d.fix_due_date, d.fixed_date, d.remarks, d.is_deleted, d.updated_at, d.pjt_id, COALESCE(u.name, d.assignee) as assigneeName, ut.TEST_CASE_NAME as testName, (CASE d.priority WHEN 'CR' THEN '긴급' WHEN 'HI' THEN '높음' WHEN 'MD' THEN '보통' WHEN 'LO' THEN '낮음' ELSE d.priority END) as priorityName, (CASE d.status WHEN 'NEW' THEN '신규' WHEN 'IPR' THEN '진행중' WHEN 'FIX' THEN '해결' WHEN 'REO' THEN '재오픈' WHEN 'COM' THEN '완료' ELSE d.status END) as statusName FROM defect d LEFT JOIN users u ON d.assignee = u.user_id LEFT JOIN unit_test_case ut ON d.test_id = ut.id WHERE d.test_id = #{testId} AND d.is_deleted = 'N' ORDER BY d.created_at DESC
LIMIT 1
) A

SELECT id as ID, test_id as testId, name as name, description as description, priority as priority, status as status, created_at as createdAt, assignee as assignee, fix_due_date as fixDueDate, fixed_date as fixedDate, remarks as remarks, is_deleted as isDeleted, updated_at as updatedAt, pjt_id as pjtId, assigneeName, testName, priorityName, statusName FROM ( SELECT d.id, d.test_id, d.name, d.description, d.priority, d.status, d.created_at, d.assignee, d.fix_due_date, d.fixed_date, d.remarks, d.is_deleted, d.updated_at, d.pjt_id, COALESCE(u.name, d.assignee) as assigneeName, ut.TEST_CASE_NAME as testName, (CASE d.priority WHEN 'CR' THEN '긴급' WHEN 'HI' THEN '높음' WHEN 'MD' THEN '보통' WHEN 'LO' THEN '낮음' ELSE d.priority END) as priorityName, (CASE d.status WHEN 'NEW' THEN '신규' WHEN 'IPR' THEN '진행중' WHEN 'FIX' THEN '해결' WHEN 'REO' THEN '재오픈' WHEN 'COM' THEN '완료' ELSE d.status END) as statusName FROM defect d LEFT JOIN users u ON d.assignee = u.user_id LEFT JOIN unit_test_case ut ON d.test_id = ut.id WHERE d.is_deleted = 'N' AND d.status != 'COM' AND d.fix_due_date IS NOT NULL
AND d.fix_due_date <= DATE_ADD(NOW(), INTERVAL 3 DAY)
AND d.pjt_id = #{pjtId}
AND d.assignee = #{assignee}
ORDER BY d.fix_due_date ASC ) A

SELECT DATE(created_at) as createdDate, COUNT(*) as totalCount, SUM(CASE WHEN status = 'COM' THEN 1 ELSE 0 END) as completedCount, SUM(CASE WHEN status = 'IPR' THEN 1 ELSE 0 END) as inProgressCount, SUM(CASE WHEN status = 'NEW' THEN 1 ELSE 0 END) as newCount FROM defect WHERE is_deleted = 'N'
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
AND pjt_id = #{pjtId}
GROUP BY DATE(created_at) ORDER BY createdDate DESC

SELECT id as ID, test_id as testId, name as name, description as description, priority as priority, status as status, created_at as createdAt, assignee as assignee, fix_due_date as fixDueDate, fixed_date as fixedDate, remarks as remarks, is_deleted as isDeleted, updated_at as updatedAt, pjt_id as pjtId, assigneeName, testName, priorityName, statusName FROM ( SELECT d.id, d.test_id, d.name, d.description, d.priority, d.status, d.created_at, d.assignee, d.fix_due_date, d.fixed_date, d.remarks, d.is_deleted, d.updated_at, d.pjt_id, COALESCE(u.name, d.assignee) as assigneeName, ut.TEST_CASE_NAME as testName, (CASE d.priority WHEN 'CR' THEN '긴급' WHEN 'HI' THEN '높음' WHEN 'MD' THEN '보통' WHEN 'LO' THEN '낮음' ELSE d.priority END) as priorityName, (CASE d.status WHEN 'NEW' THEN '신규' WHEN 'IPR' THEN '진행중' WHEN 'FIX' THEN '해결' WHEN 'REO' THEN '재오픈' WHEN 'COM' THEN '완료' ELSE d.status END) as statusName FROM defect d LEFT JOIN users u ON d.assignee = u.user_id LEFT JOIN unit_test_case ut ON d.test_id = ut.id WHERE d.is_deleted = 'N'
AND d.pjt_id = #{pjtId}
AND d.status = #{status}
ORDER BY d.created_at DESC ) A

SELECT COUNT(*)
FROM defect 
WHERE name = #{name}
AND test_id = #{testId}
AND is_deleted = 'N'


    AND id != #{id}



    AND pjt_id = #{pjtId}

SELECT id as ID, test_id as testId, name as name, description as description, priority as priority, status as status, created_at as createdAt, assignee as assignee, fix_due_date as fixDueDate, fixed_date as fixedDate, remarks as remarks, is_deleted as isDeleted, updated_at as updatedAt, pjt_id as pjtId, assigneeName, testName, priorityName, statusName FROM ( SELECT d.id, d.test_id, d.name, d.description, d.priority, d.status, d.created_at, d.assignee, d.fix_due_date, d.fixed_date, d.remarks, d.is_deleted, d.updated_at, d.pjt_id, COALESCE(u.name, d.assignee) as assigneeName, ut.TEST_CASE_NAME as testName, (CASE d.priority WHEN 'CR' THEN '긴급' WHEN 'HI' THEN '높음' WHEN 'MD' THEN '보통' WHEN 'LO' THEN '낮음' ELSE d.priority END) as priorityName, (CASE d.status WHEN 'NEW' THEN '신규' WHEN 'IPR' THEN '진행중' WHEN 'FIX' THEN '해결' WHEN 'REO' THEN '재오픈' WHEN 'COM' THEN '완료' ELSE d.status END) as statusName FROM defect d LEFT JOIN users u ON d.assignee = u.user_id INNER JOIN unit_test_case ut ON d.test_id = ut.id WHERE d.is_deleted = 'N'
AND d.pjt_id = #{pjtId}
ORDER BY d.created_at DESC ) A
